var episodes = $input.all().filter(function(item) { return item.json.id; });

if (episodes.length === 0) {
  throw new Error("No episodes with status audio_ready. Run WF-05 first.");
}

var ep = episodes[0].json;

return [{
  json: {
    episode_id: ep.id,
    title: ep.title,
    script: ep.script,
    audio_url: ep.audio_url,
    status: ep.status,
    created_at: ep.created_at
  }
}];

var ep = $json;
var pubDate = new Date(ep.created_at || Date.now()).toUTCString();
var description = (ep.script || "").substring(0, 500).replace(/[<>&]/g, "");

var rssItem = "<item>\n" +
  "  <title>" + ep.title + "</title>\n" +
  "  <description><![CDATA[" + description + "...]]></description>\n" +
  '  <enclosure url="' + ep.audio_url + '" length="0" type="audio/mpeg"/>\n' +
  '  <guid isPermaLink="false">' + ep.episode_id + "</guid>\n" +
  "  <pubDate>" + pubDate + "</pubDate>\n" +
  "  <itunes:duration>300</itunes:duration>\n" +
  "  <itunes:summary>" + description + "...</itunes:summary>\n" +
  "</item>";

return [{
  json: {
    episode_id: ep.episode_id,
    title: ep.title,
    script: ep.script,
    audio_url: ep.audio_url,
    rss_item: rssItem,
    description: description
  }
}];

